// ListRequestRecordsPage 供 admin 请求记录列表（富化版）按过滤条件分页倒序列出。
// 关联（均 1:1 或标量子查询，不放大行数）：usage_records（token）、cost_snapshots（平台成本 + 分项）、
// ledger_entries 净扣费（用户实际扣费）、api_keys→routes（线路名，当前绑定，快照见批二）、
// final channel 名、经过的渠道链（attempts 按序 string_agg）、routing_decision_traces（sticky 摘要）。
// 列表故意不 SELECT internal_error_detail（SQL 层脱敏，详情上游源站按 ?include_internal 返回）。
// latency/ttft/tps 由 Go 侧用时间戳 + output_tokens 计算，不在此列。
// 线路名优先用请求级快照 route_id（Key 换绑不影响历史）；历史行 route_id 为 NULL 时回落到 Key 当前绑定。
// 模型元信息（显示名 / owned_by）按请求模型 id 关联；请求模型不在库时为 NULL。
// 先在 request_records 上完成过滤、精确计数与分页，再只对当前页执行富字段 JOIN/子查询；
// 避免 COUNT(*) OVER() 迫使数据库为全部匹配请求构造完整富化结果。
func (q *Queries) ListRequestRecordsPage(ctx context.Context, arg ListRequestRecordsPageParams) ([]ListRequestRecordsPageRow, error) {
	rows, err := q.db.Query(ctx, listRequestRecordsPage,
		arg.ChannelID,
		arg.AttemptID,
		arg.ScoringSample,
		arg.SortField,
		arg.SortDesc,
		arg.UserID,
		arg.ApiKeyID,
		arg.RequestID,
		arg.Status,
		arg.Model,
		arg.RouteID,
		arg.FromTime,
		arg.ToTime,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRequestRecordsPageRow
	for rows.Next() {
		var i ListRequestRecordsPageRow
		if err := rows.Scan(
			&i.TotalCount,
			&i.ID,
			&i.RequestID,
			&i.UserID,
			&i.ApiKeyID,
			&i.RequestedModelID,
			&i.IngressProtocol,
			&i.Endpoint,
			&i.ResponseModelID,
			&i.ResponseProtocol,
			&i.ResponseID,
			&i.Stream,
			&i.Status,
			&i.FinalProviderID,
			&i.FinalChannelID,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.DeliveryStatus,
			&i.GatewayFirstTokenAt,
			&i.ResponseCompletedAt,
			&i.StartedAt,
			&i.CompletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RequestedServiceTier,
			&i.ActualServiceTier,
			&i.SettledServiceTier,
			&i.ServiceTierResolution,
			&i.ApiKeyName,
			&i.ApiKeyPrefix,
			&i.ApiKeyPlaintext,
			&i.UncachedInputTokens,
			&i.CacheReadInputTokens,
			&i.CacheWrite5mInputTokens,
			&i.CacheWrite1hInputTokens,
			&i.CacheWrite30mInputTokens,
			&i.OutputTokensTotal,
			&i.ReasoningOutputTokens,
			&i.TotalCostAmount,
			&i.UncachedInputCostAmount,
			&i.CacheReadInputCostAmount,
			&i.CacheWrite5mInputCostAmount,
			&i.CacheWrite1hInputCostAmount,
			&i.CacheWrite30mInputCostAmount,
			&i.OutputCostAmount,
			&i.ReasoningOutputCostAmount,
			&i.UncachedInputCost,
			&i.CacheReadInputCost,
			&i.CacheWrite5mInputCost,
			&i.CacheWrite1hInputCost,
			&i.CacheWrite30mInputCost,
			&i.OutputCost,
			&i.ReasoningOutputCost,
			&i.ChannelCostMultiplier,
			&i.RechargeFactor,
			&i.UncachedInputPrice,
			&i.CacheReadInputPrice,
			&i.CacheWrite5mInputPrice,
			&i.CacheWrite1hInputPrice,
			&i.CacheWrite30mInputPrice,
			&i.OutputPrice,
			&i.ReasoningOutputPrice,
			&i.PriceServiceTier,
			&i.CostServiceTier,
			&i.ModelPriceServiceTierID,
			&i.ChannelPriceServiceTierID,
			&i.TierCostSource,
			&i.UserChargeAmount,
			&i.ReasoningEffort,
			&i.ReasoningBudgetTokens,
			&i.ClientIp,
			&i.RouteName,
			&i.RoutePriceRatio,
			&i.LongContextApplied,
			&i.RouteMode,
			&i.ModelDisplayName,
			&i.ModelOwnedBy,
			&i.FinalChannelName,
			&i.ChannelChain,
			&i.RouteID,
			&i.ScoringAttemptID,
			&i.ScoringDimensions,
			&i.ScoringErrorFailure,
			&i.StickyKeyPresent,
			&i.StickyAction,
			&i.StickyReason,
			&i.StickyBeforeChannelID,
			&i.StickyAfterChannelID,
			&i.StickyPinned,
			&i.StickyPinnedNonPreferred,
			&i.StickyBeforeChannelName,
			&i.StickyAfterChannelName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const summarizeConsoleBilledRequests = `-- name: SummarizeConsoleBilledRequests :one
SELECT
    COUNT(*)::bigint AS request_count,
    COALESCE(SUM(
        COALESCE(ur.uncached_input_tokens, 0)
        + COALESCE(ur.cache_read_input_tokens, 0)
        + COALESCE(ur.cache_write_5m_input_tokens, 0)
        + COALESCE(ur.cache_write_1h_input_tokens, 0)
        + COALESCE(ur.cache_write_30m_input_tokens, 0)
        + COALESCE(ur.output_tokens_total, 0)
    ), 0)::bigint AS token_count,
    COALESCE(SUM(
        COALESCE(ur.uncached_input_tokens, 0)
        + COALESCE(ur.cache_read_input_tokens, 0)
        + COALESCE(ur.cache_write_5m_input_tokens, 0)
        + COALESCE(ur.cache_write_1h_input_tokens, 0)
        + COALESCE(ur.cache_write_30m_input_tokens, 0)
    ), 0)::bigint AS input_token_count,
    COALESCE(SUM(COALESCE(ur.output_tokens_total, 0)), 0)::bigint AS output_token_count,
    COALESCE(SUM((
        SELECT COALESCE(SUM(
            CASE
                WHEN le.entry_type IN ('debit', 'adjustment_debit') THEN le.amount
                WHEN le.entry_type IN ('credit', 'refund', 'adjustment_credit') THEN -le.amount
                ELSE 0
            END
        ), 0)
        FROM ledger_entries le
        WHERE le.request_record_id = r.id AND le.currency = 'USD'
    )), 0)::numeric AS charge_usd,
    COALESCE(
        AVG(EXTRACT(EPOCH FROM (r.completed_at - r.started_at)) * 1000)
            FILTER (WHERE r.completed_at IS NOT NULL AND r.started_at IS NOT NULL),
        0
    )::float8 AS average_latency_ms
FROM request_records r
JOIN usage_records ur ON ur.request_record_id = r.id
WHERE r.user_id = $1
  AND (
      SELECT COALESCE(SUM(
          CASE
              WHEN le.entry_type IN ('debit', 'adjustment_debit') THEN le.amount
              WHEN le.entry_type IN ('credit', 'refund', 'adjustment_credit') THEN -le.amount
              ELSE 0
          END
      ), 0)
      FROM ledger_entries le
      WHERE le.request_record_id = r.id AND le.currency = 'USD'
  ) > 0
  AND ($2::timestamptz IS NULL OR r.created_at >= $2::timestamptz)
  AND ($3::timestamptz IS NULL OR r.created_at < $3::timestamptz)
`

type SummarizeConsoleBilledRequestsParams struct {
	UserID   int64
	FromTime pgtype.Timestamptz
	ToTime   pgtype.Timestamptz
}

type SummarizeConsoleBilledRequestsRow struct {
	RequestCount     int64
	TokenCount       int64
	InputTokenCount  int64
	OutputTokenCount int64
	ChargeUsd        pgtype.Numeric
	AverageLatencyMs float64
}

// 账户累计实际扣费请求。from_time/to_time 可空（narg，NULL = 不过滤时间）。
func (q *Queries) SummarizeConsoleBilledRequests(ctx context.Context, arg SummarizeConsoleBilledRequestsParams) (SummarizeConsoleBilledRequestsRow, error) {
	row := q.db.QueryRow(ctx, summarizeConsoleBilledRequests, arg.UserID, arg.FromTime, arg.ToTime)
	var i SummarizeConsoleBilledRequestsRow
	err := row.Scan(
		&i.RequestCount,
		&i.TokenCount,
		&i.InputTokenCount,
		&i.OutputTokenCount,
		&i.ChargeUsd,
		&i.AverageLatencyMs,
	)
	return i, err
}
